import run_benchmark as scaffold

def java_tool(name):
    candidates = []
    home = os.environ.get('JAVA_HOME')
    if home: candidates += [Path(home)/'bin'/(name+'.exe'), Path(home)/'bin'/name]
    for n in (name, name+'.exe'):
        found = shutil.which(n)
        if found: candidates.append(Path(found))
    fallback = Path('D:/Android/jbr/bin')
    candidates += [fallback/(name+'.exe'), fallback/name]
    for candidate in candidates:
        if candidate.is_file(): return str(candidate)
    raise FileNotFoundError(f'Cannot find {name}; set JAVA_HOME or add a JDK to PATH')

def put(rel, value):
    p = BUILD / 'src' / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(value, encoding='utf-8')

