def main():
    resolved = BUILD.resolve()
    if resolved.parent != HERE.resolve() or resolved.name != 'build':
        raise SystemExit(f'Refusing to clean unverified build path: {resolved}')
    if BUILD.exists(): shutil.rmtree(BUILD)
    BUILD.mkdir(parents=True)
    for rel, source in STUBS.items(): put(rel, source)
    for name in ('SyncCoordinator.java', 'SiteGateway.java'):
        put('cn/lut/schedule/' + name, (PROD / name).read_text(encoding='utf-8-sig'))
    output = BUILD / 'classes'; output.mkdir()
    sources = [str(p) for p in (BUILD/'src').rglob('*.java')]
    subprocess.run([java_tool('javac'), '-encoding', 'UTF-8', '-d', str(output), *sources], check=True, timeout=30)
    proc = subprocess.run([java_tool('java'), '-cp', str(output), 'cn.lut.schedule.Harness'], capture_output=True, text=True, check=True, timeout=30)
    # Harness emits Java map syntax for nested objects; keep console output as a compact validated record.
    text = proc.stdout.strip()
    result = {'scope': 'synthetic virtual-time harness only; production SyncCoordinator and SiteGateway source; no live network, Android SQLite, Cookie storage, or UI frame measurement',
              'productionSha256': {n: hashlib.sha256((PROD/n).read_bytes()).hexdigest().upper() for n in ('SyncCoordinator.java','SiteGateway.java')},
              'scenarioCount': 15, 'harnessOutput': text}
    (BUILD/'results.json').write_text(json.dumps(result, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    print(json.dumps(result, ensure_ascii=False, indent=2))

if __name__ == '__main__': main()
